function main(i) {
  const map = {};
  for (const it of i.items) {
    const d = it.data;
    const rep = d.rep || '(担当者なし)';
    if (!map[rep]) map[rep] = { rep: rep, visits: 0, prospect: 0, notes: [] };
    map[rep].visits += Number(d.visits) || 0;
    map[rep].prospect += Number(d.prospect) || 0;
    if (d.note) map[rep].notes.push(String(d.note));
  }
  const list = Object.values(map).sort((a, b) => (a.rep < b.rep ? -1 : a.rep > b.rep ? 1 : 0));
  const rows = list.map((r) => ({ week_start: i.start, rep: r.rep, visits: r.visits, prospect: r.prospect }));
  const digest = list.map((r) => '【' + r.rep + '】訪問 ' + r.visits + ' 件・見込み額 ' + r.prospect + ' 円\n所感: ' + (r.notes.join(' / ') || 'なし')).join('\n\n');
  return { rows: rows, digest: digest || '先週の日報はありません。', count: rows.length };
}

function main(i) {
  const m = {};
  let tv = 0, tp = 0;
  for (const it of i.items) {
    const d = it.data || {};
    const k = d.rep || '(未記入)';
    if (!m[k]) m[k] = { rep: k, visits: 0, prospect: 0, notes: [] };
    const v = Number(d.visits) || 0;
    const p = Number(d.prospect) || 0;
    m[k].visits += v;
    m[k].prospect += p;
    tv += v;
    tp += p;
    if (d.note) m[k].notes.push(d.report_date + ': ' + d.note);
  }
  const groups = Object.values(m).map(g => ({ rep: g.rep, visits: g.visits, prospect: g.prospect }));
  const text = Object.values(m).map(g => '■' + g.rep + '\n訪問件数: ' + g.visits + '件 / 見込み額: ' + g.prospect + '円\n所感:\n' + (g.notes.join('\n') || 'なし')).join('\n\n') + '\n\n【全体】訪問件数: ' + tv + '件 / 見込み額: ' + tp + '円';
  return { groups, text, count: i.items.length };
}

