    const code = String(r.data.code ?? '');
    const name = String(r.data.name ?? '');
    const qty = Number(r.data.reorder_qty ?? 0);
    rows.push([code, name, qty]);
    if (!existing.has(code) && !seen.has(code)) {
      seen.add(code);
      newRows.push({ data: { code: code, name: name, order_qty: qty, status: '下書き' } });
    }
  }
  return { table: { columns: ['品番', '品名', '発注数'], rows: rows }, new_rows: newRows };
